  "ka": {"sheet_title": "თქვენი კონფიდენციალურობა პრიორიტეტულია", "sheet_body": "თქვენი ჯანმრთელობის მონაცემები არასდროს გამოიყენება რეკლამებისა თუ ანალიტიკისთვის. ეს არჩევანი ეხება მხოლოდ აპლიკაციის გამოყენების სტატისტიკას და რეკლამებს. პარამეტრების შეცვლა შეგიძლიათ ნებისმიერ დროს „კონფიდენციალურობის“ განყოფილებაში.", "analytics_title": "ანალიტიკა", "analytics_desc": "ანონიმური სტატისტიკა, რომელიც გვეხმარება აპლიკაციის გაუმჯობესებაში (Google Firebase). ციკლის თარიღები, სიმპტომები და ჯანმრთელობის სხვა ჩანაწერები არ შედის.", "ads_title": "პერსონალიზებული რეკლამები", "ads_desc": "უფასო ვერსიაში თქვენს ინტერესებზე მორგებული რეკლამები (Google AdMob). გამორთვის შემთხვევაში, იხილავთ ზოგად რეკლამებს.", "attribution_title": "რეკლამის გაზომვა", "attribution_desc": "ზომავს, თუ რომელმა რეკლამამ მოგიყვანათ Anacan-ში (Meta). iPhone-ზე ასევე გამოჩნდება Apple-ის ნებართვის ფანჯარა.", "essential_title": "აუცილებელი", "essential_desc": "ანგარიში, სინქრონიზაცია, შეხსენებები და უსაფრთხოება. ყოველთვის ჩართულია.", "accept_all": "ყველაფრის მიღება", "reject_all": "მხოლოდ აუცილებელი", "customize": "არჩევანის მორგება", "save": "არჩევანის შენახვა", "section_title": "თანხმობის პარამეტრები", "section_desc": "ვრცელდება ამ მოწყობილობაზე. გადამრთველის გამორთვა მონაცემების გაგზავნას დაუყოვნებლივ წყვეტს.", "ump_link": "Google-ის რეკლამის თანხმობის პარამეტრები", "policy_link": "კონფიდენციალურობის პოლიტიკა", "settings_row": "თანხმობის პარამეტრები", "settings_row_desc": "ანალიტიკა, რეკლამები და გაზომვა", "saved": "თქვენი არჩევანი შენახულია", "always_on": "ყოველთვის ჩართულია"},
  "kk": {"sheet_title": "Құпиялылығыңыз бәрінен маңызды", "sheet_body": "Денсаулық жазбаларыңыз жарнама немесе аналитика үшін ешқашан бөлісілмейді. Бұл баптаулар тек қолданбаны пайдалану статистикасы мен жарнамаларға қатысты. Оларды кез келген уақытта «Құпиялылық» бөлімінде өзгерте аласыз.", "analytics_title": "Аналитика", "analytics_desc": "Қолданбаны жақсартуға көмектесетін анонимді пайдалану статистикасы (Google Firebase). Цикл күндері, симптомдар және басқа да денсаулық жазбалары қосылмайды.", "ads_title": "Жекелендірілген жарнама", "ads_desc": "Тегін нұсқадағы қызығушылықтарыңызға негізделген жарнамалар (Google AdMob). Өшірілген болса, жалпы жарнамаларды көресіз.", "attribution_title": "Жарнаманы өлшеу", "attribution_desc": "Сізді Anacan қолданбасына қай жарнама әкелгенін өлшейді (Meta). iPhone-да Apple рұқсат терезесі де пайда болады.", "essential_title": "Міндетті", "essential_desc": "Аккаунт, синхрондау, еске салғыштар және қауіпсіздік. Әрқашан қосулы.", "accept_all": "Барлығын қабылдау", "reject_all": "Тек міндеттілері", "customize": "Таңдауды баптау", "save": "Таңдауымды сақтау", "section_title": "Келісім баптаулары", "section_desc": "Осы құрылғыға қолданылады. Қосқышты өшіру деректерді жіберуді бірден тоқтатады.", "ump_link": "Google жарнама келісімінің баптаулары", "policy_link": "Құпиялылық саясаты", "settings_row": "Келісім баптаулары", "settings_row_desc": "Аналитика, жарнама және өлшеу", "saved": "Таңдауыңыз сақталды", "always_on": "Әрқашан қосулы"},
  "uz": {"sheet_title": "Maxfiyligingiz — birinchi o'rinda", "sheet_body": "Sog'lig'ingizga oid ma'lumotlar reklama yoki tahlil uchun hech qachon ulashilmaydi. Ushbu tanlovlar faqat ilovadan foydalanish statistikasi va reklamalarga tegishli. Ularni istalgan vaqtda Maxfiylik bo'limida o'zgartirishingiz mumkin.", "analytics_title": "Analitika", "analytics_desc": "Ilovani yaxshilashga yordam beradigan anonim foydalanish statistikasi (Google Firebase). Hayz sikli sanalari, alomatlar va boshqa salomatlik ma'lumotlari bunga kirmaydi.", "ads_title": "Shaxsiylashtirilgan reklamalar", "ads_desc": "Ilovaning bepul talqinida qiziqishlaringizga asoslangan reklamalar (Google AdMob). Agar o'chirilsa, umumiy reklamalarni ko'rasiz.", "attribution_title": "Reklama samaradorligi", "attribution_desc": "Sizni Anacan ilovasiga qaysi reklama olib kelganini o'lchaydi (Meta). iPhone qurilmalarida Apple'ning ruxsat so'rash oynasi ham paydo bo'ladi.", "essential_title": "Zaruriy", "essential_desc": "Hisob, sinxronizatsiya, eslatmalar va xavfsizlik. Har doim yoniq.", "accept_all": "Hammasini qabul qilish", "reject_all": "Faqat zaruriylari", "customize": "Tanlovlarni sozlash", "save": "Tanlovlarimni saqlash", "section_title": "Rozilik tanlovlari", "section_desc": "Ushbu qurilmaga amal qiladi. Tugmani o'chirish ma'lumot yuborishni darhol to'xtatadi.", "ump_link": "Google reklama roziligi sozlamalari", "policy_link": "Maxfiylik siyosati", "settings_row": "Rozilik tanlovlari", "settings_row_desc": "Analitika, reklamalar va o'lchovlar", "saved": "Tanlovlaringiz saqlandi", "always_on": "Har doim yoniq"},
  "zh": {"sheet_title": "您的隐私至上", "sheet_body": "您的健康记录绝不会用于广告或分析。这些选项仅涵盖应用使用统计和广告。您可以随时在“隐私”设置中进行更改。", "analytics_title": "分析统计", "analytics_desc": "帮助我们改进应用的匿名使用统计信息（Google Firebase）。经期日期、症状及其他健康记录均不包含在内。", "ads_title": "个性化广告", "ads_desc": "免费版中基于您兴趣展示的广告（Google AdMob）。若关闭，您将看到普通广告。", "attribution_title": "广告归因", "attribution_desc": "衡量是哪则广告将您带到了 Anacan（Meta）。在 iPhone 上，系统还会弹出 Apple 的权限许可窗口。", "essential_title": "必要服务", "essential_desc": "账户、同步、提醒和安全性。始终开启。", "accept_all": "全部接受", "reject_all": "仅保留必要服务", "customize": "自定义选项", "save": "保存我的选择", "section_title": "隐私许可选项", "section_desc": "适用于此设备。关闭开关后将立即停止发送数据。", "ump_link": "Google 广告许可设置", "policy_link": "隐私政策", "settings_row": "隐私许可选项", "settings_row_desc": "分析、广告和归因", "saved": "您的选择已保存", "always_on": "始终开启"},
  "id": {"sheet_title": "Privasi Bunda adalah yang utama", "sheet_body": "Catatan kesehatan Bunda tidak pernah dibagikan untuk iklan atau analitik. Pilihan ini hanya mencakup statistik penggunaan aplikasi dan iklan. Bunda dapat mengubahnya kapan saja di Privasi.", "analytics_title": "Analitik", "analytics_desc": "Statistik penggunaan anonim yang membantu kami meningkatkan aplikasi (Google Firebase). Tanggal siklus, gejala, dan catatan kesehatan lainnya tidak disertakan.", "ads_title": "Iklan yang dipersonalisasi", "ads_desc": "Iklan di versi gratis berdasarkan minat Bunda (Google AdMob). Jika dimatikan, Bunda akan melihat iklan umum.", "attribution_title": "Pengukuran iklan", "attribution_desc": "Mengukur iklan mana yang membawa Bunda ke Anacan (Meta). Di iPhone, jendela izin Apple juga akan muncul.", "essential_title": "Esensial", "essential_desc": "Akun, sinkronisasi, pengingat, dan keamanan. Selalu aktif.", "accept_all": "Terima semua", "reject_all": "Hanya esensial", "customize": "Sesuaikan pilihan", "save": "Simpan pilihan saya", "section_title": "Pilihan persetujuan", "section_desc": "Berlaku untuk perangkat ini. Mematikan tombol akan langsung menghentikan pengiriman.", "ump_link": "Pengaturan persetujuan iklan Google", "policy_link": "Kebijakan privasi", "settings_row": "Pilihan persetujuan", "settings_row_desc": "Analitik, iklan, dan pengukuran", "saved": "Pilihan Bunda telah disimpan", "always_on": "Selalu aktif"},
  "fr": {"sheet_title": "Votre vie privée est notre priorité", "sheet_body": "Vos données de santé ne sont jamais partagées à des fins publicitaires ou d'analyse. Ces choix concernent uniquement les statistiques d'utilisation et les publicités. Vous pouvez les modifier à tout moment dans Confidentialité.", "analytics_title": "Analyses", "analytics_desc": "Statistiques d'utilisation anonymes nous aidant à améliorer l'application (Google Firebase). Les dates de cycle, symptômes et autres données de santé sont exclus.", "ads_title": "Publicités personnalisées", "ads_desc": "Publicités dans la version gratuite basées sur vos centres d'intérêt (Google AdMob). Si désactivé, vous verrez des publicités génériques.", "attribution_title": "Mesure publicitaire", "attribution_desc": "Mesure quelle publicité vous a menée vers Anacan (Meta). Sur iPhone, la fenêtre d'autorisation d'Apple apparaîtra également.", "essential_title": "Essentiel", "essential_desc": "Compte, synchronisation, rappels et sécurité. Toujours activé.", "accept_all": "Tout accepter", "reject_all": "Essentiel uniquement", "customize": "Personnaliser mes choix", "save": "Enregistrer mes choix", "section_title": "Choix de consentement", "section_desc": "S'applique à cet appareil. Désactiver une option interrompt l'envoi immédiatement.", "ump_link": "Paramètres de consentement publicitaire Google", "policy_link": "Politique de confidentialité", "settings_row": "Choix de consentement", "settings_row_desc": "Analyses, publicités et mesures", "saved": "Vos choix ont été enregistrés", "always_on": "Toujours activé"},
  "es": {"sheet_title": "Tu privacidad es lo primero", "sheet_body": "Tus registros de salud nunca se comparten para publicidad o análisis. Estas opciones solo cubren las estadísticas de uso de la aplicación y los anuncios. Puedes cambiarlas en cualquier momento en Privacidad.", "analytics_title": "Análisis", "analytics_desc": "Estadísticas de uso anónimas que nos ayudan a mejorar la aplicación (Google Firebase). Las fechas del ciclo, síntomas y otros registros de salud no están incluidos.", "ads_title": "Anuncios personalizados", "ads_desc": "Anuncios en la versión gratuita basados en tus intereses (Google AdMob). Si los desactivas, verás anuncios generales.", "attribution_title": "Medición de anuncios", "attribution_desc": "Mide qué anuncio te trajo a Anacan (Meta). En iPhone, también aparecerá la ventana de permisos de Apple.", "essential_title": "Esencial", "essential_desc": "Cuenta, sincronización, recordatorios y seguridad. Siempre activado.", "accept_all": "Aceptar todo", "reject_all": "Solo lo esencial", "customize": "Personalizar opciones", "save": "Guardar mis opciones", "section_title": "Opciones de consentimiento", "section_desc": "Se aplica a este dispositivo. Desactivar un interruptor detiene el envío de inmediato.", "ump_link": "Configuración de consentimiento de anuncios de Google", "policy_link": "Política de privacidad", "settings_row": "Opciones de consentimiento", "settings_row_desc": "Análisis, anuncios y medición", "saved": "Tus opciones han sido guardadas", "always_on": "Siempre activado"},
  "pt": {"sheet_title": "A sua privacidade em primeiro lugar", "sheet_body": "Os seus registos de saúde nunca são partilhados para anúncios ou análises. Estas opções abrangem apenas estatísticas de utilização da aplicação e anúncios. Pode alterá-las a qualquer momento em Privacidade.", "analytics_title": "Análises", "analytics_desc": "Estatísticas de utilização anónimas que nos ajudam a melhorar a aplicação (Google Firebase). Datas do ciclo, sintomas e outros registos de saúde não estão incluídos.", "ads_title": "Anúncios personalizados", "ads_desc": "Anúncios na versão gratuita baseados nos seus interesses (Google AdMob). Se desativar, verá anúncios gerais.", "attribution_title": "Medição de anúncios", "attribution_desc": "Mede qual o anúncio que a trouxe à Anacan (Meta). No iPhone, também aparecerá a janela de permissão da Apple.", "essential_title": "Essenciais", "essential_desc": "Conta, sincronização, lembretes e segurança. Sempre ativos.", "accept_all": "Aceitar tudo", "reject_all": "Apenas essenciais", "customize": "Personalizar opções", "save": "Guardar as minhas opções", "section_title": "Opções de consentimento", "section_desc": "Aplica-se a este dispositivo. Desativar uma opção interrompe o envio imediatamente.", "ump_link": "Definições de consentimento de anúncios do Google", "policy_link": "Política de privacidade", "settings_row": "Opções de consentimento", "settings_row_desc": "Análises, anúncios e medição", "saved": "As suas opções foram guardadas", "always_on": "Sempre ativo"},
  "vi": {"sheet_title": "Quyền riêng tư của bạn là ưu tiên hàng đầu", "sheet_body": "Hồ sơ sức khỏe của bạn không bao giờ được chia sẻ để quảng cáo hoặc phân tích. Các lựa chọn này chỉ áp dụng cho số liệu thống kê sử dụng ứng dụng và quảng cáo. Bạn có thể thay đổi bất kỳ lúc nào trong mục Quyền riêng tư.", "analytics_title": "Phân tích", "analytics_desc": "Số liệu thống kê sử dụng ẩn danh giúp chúng tôi cải thiện ứng dụng (Google Firebase). Ngày chu kỳ, triệu chứng và các hồ sơ sức khỏe khác không bao gồm trong này.", "ads_title": "Quảng cáo cá nhân hóa", "ads_desc": "Quảng cáo trong phiên bản miễn phí dựa trên sở thích của bạn (Google AdMob). Nếu tắt, bạn sẽ thấy các quảng cáo chung.", "attribution_title": "Đo lường quảng cáo", "attribution_desc": "Đo lường xem quảng cáo nào đã đưa bạn đến với Anacan (Meta). Trên iPhone, cửa sổ xin phép của Apple cũng sẽ xuất hiện.", "essential_title": "Cần thiết", "essential_desc": "Tài khoản, đồng bộ hóa, nhắc nhở và bảo mật. Luôn bật.", "accept_all": "Chấp nhận tất cả", "reject_all": "Chỉ các mục cần thiết", "customize": "Tùy chỉnh lựa chọn", "save": "Lưu lựa chọn của tôi", "section_title": "Lựa chọn chấp thuận", "section_desc": "Áp dụng cho thiết bị này. Việc tắt nút gạt sẽ dừng gửi dữ liệu ngay lập tức.", "ump_link": "Cài đặt chấp thuận quảng cáo Google", "policy_link": "Chính sách quyền riêng tư", "settings_row": "Lựa chọn chấp thuận", "settings_row_desc": "Phân tích, quảng cáo và đo lường", "saved": "Lựa chọn của bạn đã được lưu", "always_on": "Luôn bật"},
  "hi": {"sheet_title": "आपकी गोपनीयता हमारी प्राथमिकता है", "sheet_body": "आपके स्वास्थ्य रिकॉर्ड कभी भी विज्ञापनों या एनालिटिक्स के लिए साझा नहीं किए जाते हैं। ये विकल्प केवल ऐप उपयोग के आंकड़ों और विज्ञापनों पर लागू होते हैं। आप इन्हें 'गोपनीयता' (Privacy) में कभी भी बदल सकते हैं।", "analytics_title": "एनालिटिक्स", "analytics_desc": "अनाम उपयोग के आंकड़े जो हमें ऐप को बेहतर बनाने में मदद करते हैं (Google Firebase)। मासिक धर्म की तारीखें, लक्षण और अन्य स्वास्थ्य रिकॉर्ड इसमें शामिल नहीं हैं।", "ads_title": "व्यक्तिगत विज्ञापन", "ads_desc": "मुफ़्त वर्ज़न में आपकी रुचियों पर आधारित विज्ञापन (Google AdMob)। यदि बंद है, तो आपको सामान्य विज्ञापन दिखाई देंगे।", "attribution_title": "विज्ञापन मापन", "attribution_desc": "यह मापता है कि किस विज्ञापन के माध्यम से आप Anacan तक पहुँचे (Meta)। iPhone पर, Apple की अनुमति विंडो भी दिखाई देगी।", "essential_title": "आवश्यक", "essential_desc": "अकाउंट, सिंक, रिमाइंडर और सुरक्षा। हमेशा चालू।", "accept_all": "सभी स्वीकार करें", "reject_all": "केवल आवश्यक", "customize": "विकल्प कस्टमाइज़ करें", "save": "मेरे विकल्प सहेजें", "section_title": "सहमति विकल्प", "section_desc": "यह इस डिवाइस पर लागू होता है। स्विच बंद करने पर डेटा भेजना तुरंत रुक जाता है।", "ump_link": "Google विज्ञापन सहमति सेटिंग्स", "policy_link": "गोपनीयता नीति", "settings_row": "सहमति विकल्प", "settings_row_desc": "एनालिटिक्स, विज्ञापन और मापन", "saved": "आपके विकल्प सहेज लिए गए हैं", "always_on": "हमेशा चालू"},
  "ja": {"sheet_title": "あなたのプライバシーを最優先に", "sheet_body": "健康に関する記録が広告や分析のために共有されることは一切ありません。ここでの設定は、アプリの利用統計と広告のみに適用されます。設定は「プライバシー」からいつでも変更できます。", "analytics_title": "アナリティクス", "analytics_desc": "アプリ改善に役立つ匿名の利用統計です（Google Firebase）。生理日、症状、その他の健康記録は含まれません。", "ads_title": "パーソナライズ広告", "ads_desc": "無料版で表示される、あなたの興味・関心に合わせた広告です（Google AdMob）。オフにすると、一般的な広告が表示されます。", "attribution_title": "広告効果の測定", "attribution_desc": "どの広告経由でAnacanをインストールしたかを測定します（Meta）。iPhoneでは、Appleの許可ウィンドウも表示されます。", "essential_title": "必須機能", "essential_desc": "アカウント、同期、リマインダー、セキュリティ。常にオンになります。", "accept_all": "すべて同意する", "reject_all": "必須機能のみ", "customize": "設定をカスタマイズ", "save": "設定を保存する", "section_title": "同意設定", "section_desc": "この端末に適用されます。スイッチをオフにすると、直ちにデータの送信が停止されます。", "ump_link": "Google広告の同意設定", "policy_link": "プライバシーポリシー", "settings_row": "同意設定", "settings_row_desc": "アナリティクス、広告、効果測定", "saved": "設定を保存しました", "always_on": "常にオン"},
  "ko": {"sheet_title": "개인정보 보호를 최우선으로 생각합니다", "sheet_body": "사용자의 건강 기록은 광고나 분석 목적으로 절대 공유되지 않습니다. 아래 설정은 앱 사용 통계 및 광고에만 적용됩니다. 설정의 '개인정보 보호'에서 언제든지 변경하실 수 있습니다.", "analytics_title": "앱 분석", "analytics_desc": "앱 개선을 위한 익명 사용 통계입니다(Google Firebase). 생리 주기, 증상 및 기타 건강 기록은 포함되지 않습니다.", "ads_title": "맞춤형 광고", "ads_desc": "사용자의 관심사를 기반으로 한 무료 버전 광고입니다(Google AdMob). 비활성화 시 일반 광고가 표시됩니다.", "attribution_title": "광고 측정", "attribution_desc": "어떤 광고를 통해 Anacan에 방문하셨는지 측정합니다(Meta). iPhone의 경우 Apple의 권한 요청 창이 별도로 표시될 수 있습니다.", "essential_title": "필수 항목", "essential_desc": "계정, 동기화, 알림 및 보안 관련 항목입니다. 항상 활성화됩니다.", "accept_all": "모두 동의", "reject_all": "필수 항목만 허용", "customize": "선택 사항 설정", "save": "설정 저장", "section_title": "동의 설정", "section_desc": "이 기기에 적용됩니다. 스위치를 끄면 즉시 데이터 전송이 중단됩니다.", "ump_link": "Google 광고 동의 설정", "policy_link": "개인정보 처리방침", "settings_row": "동의 설정", "settings_row_desc": "분석, 광고 및 측정", "saved": "설정이 저장되었습니다", "always_on": "항상 켬"},
  "pl": {"sheet_title": "Twoja prywatność jest najważniejsza", "sheet_body": "Twoje dane zdrowotne nigdy nie są udostępniane w celach reklamowych ani analitycznych. Te ustawienia dotyczą wyłącznie statystyk użytkowania aplikacji i reklam. Możesz je zmienić w dowolnym momencie w sekcji Prywatność.", "analytics_title": "Analityka", "analytics_desc": "Anonimowe statystyki użytkowania, które pomagają nam ulepszać Anacan (Google Firebase). Daty cyklu, objawy i inne dane zdrowotne nie są uwzględniane.", "ads_title": "Reklamy spersonalizowane", "ads_desc": "Reklamy w wersji darmowej dopasowane do Twoich zainteresowań (Google AdMob). Jeśli wyłączysz tę opcję, będziesz widzieć reklamy ogólne.", "attribution_title": "Pomiar skuteczności reklam", "attribution_desc": "Pozwala sprawdzić, która reklama przywiodła Cię do Anacan (Meta). Na iPhone'ach pojawi się również okno z prośbą o zgodę od Apple.", "essential_title": "Niezbędne", "essential_desc": "Konto, synchronizacja, przypomnienia i bezpieczeństwo. Zawsze włączone.", "accept_all": "Zaakceptuj wszystko", "reject_all": "Tylko niezbędne", "customize": "Dostosuj wybory", "save": "Zapisz moje wybory", "section_title": "Zgody i ustawienia", "section_desc": "Dotyczy tego urządzenia. Wyłączenie przełącznika natychmiast zatrzymuje przesyłanie danych.", "ump_link": "Ustawienia zgód reklamowych Google", "policy_link": "Polityka prywatności", "settings_row": "Zgody i ustawienia", "settings_row_desc": "Analityka, reklamy i pomiary", "saved": "Twoje wybory zostały zapisane", "always_on": "Zawsze włączone"},
  "nl": {"sheet_title": "Jouw privacy staat voorop", "sheet_body": "Je gezondheidsgegevens worden nooit gedeeld voor advertenties of analyses. Deze keuzes gaan alleen over app-gebruiksstatistieken en advertenties. Je kunt ze op elk moment wijzigen in Privacy.", "analytics_title": "Analyses", "analytics_desc": "Anonieme gebruiksstatistieken die ons helpen de app te verbeteren (Google Firebase). Cyclusdata, symptomen en andere gezondheidsgegevens zijn niet inbegrepen.", "ads_title": "Gepersonaliseerde advertenties", "ads_desc": "Advertenties in de gratis versie op basis van je interesses (Google AdMob). Als dit uitstaat, zie je algemene advertenties.", "attribution_title": "Advertentiemeting", "attribution_desc": "Meet welke advertentie je naar Anacan heeft gebracht (Meta). Op de iPhone verschijnt ook het toestemmingsvenster van Apple.", "essential_title": "Essentieel", "essential_desc": "Account, synchronisatie, herinneringen en beveiliging. Altijd aan.", "accept_all": "Alles accepteren", "reject_all": "Alleen essentieel", "customize": "Keuzes aanpassen", "save": "Mijn keuzes opslaan", "section_title": "Toestemmingskeuzes", "section_desc": "Geldt voor dit apparaat. Als je een schakelaar uitzet, stopt het verzenden onmiddellijk.", "ump_link": "Toestemmingsinstellingen voor Google-advertenties", "policy_link": "Privacybeleid", "settings_row": "Toestemmingskeuzes", "settings_row_desc": "Analyses, advertenties en metingen", "saved": "Je keuzes zijn opgeslagen", "always_on": "Altijd aan"},
  "sv": {"sheet_title": "Din integritet kommer först", "sheet_body": "Dina hälsodata delas aldrig för annonser eller analys. Dessa val gäller endast statistik för appanvändning och annonser. Du kan ändra dem när som helst under Integritet.", "analytics_title": "Analys", "analytics_desc": "Anonym användningsstatistik som hjälper oss att förbättra appen (Google Firebase). Menscykel, symtom och andra hälsodata inkluderas inte.", "ads_title": "Personliga annonser", "ads_desc": "Annonser i gratisversionen baserade på dina intressen (Google AdMob). Om detta är avstängt ser du generella annonser.", "attribution_title": "Annonsmätning", "attribution_desc": "Mäter vilken annons som ledde dig till Anacan (Meta). På iPhone visas även Apples eget fönster för tillåtelse.", "essential_title": "Nödvändiga", "essential_desc": "Konto, synkronisering, påminnelser och säkerhet. Alltid på.", "accept_all": "Godkänn alla", "reject_all": "Endast nödvändiga", "customize": "Anpassa val", "save": "Spara mina val", "section_title": "Samtyckesval", "section_desc": "Gäller för denna enhet. Om du stänger av en funktion upphör datadelningen omedelbart.", "ump_link": "Inställningar för Google-annonser", "policy_link": "Integritetspolicy", "settings_row": "Samtyckesval", "settings_row_desc": "Analys, annonser och mätning", "saved": "Dina val har sparats", "always_on": "Alltid på"},
  "ky": {"sheet_title": "Сиздин купуялуулугуңуз — биз үчүн биринчи орунда", "sheet_body": "Сиздин ден соолук тууралуу маалыматтарыңыз жарнама же аналитика үчүн эч качан бөлүшүлбөйт. Бул тандоолор колдонмону колдонуу статистикасына жана жарнамаларга гана тиешелүү. Сиз аларды каалаган убакта «Купуялуулук» бөлүмүнөн өзгөртө аласыз.", "analytics_title": "Аналитика", "analytics_desc": "Колдонмону жакшыртууга жардам берген анонимдүү статистика (Google Firebase). Этек кир циклдери, белгилер жана башка ден соолук маалыматтары камтылбайт.", "ads_title": "Жекелештирилген жарнамалар", "ads_desc": "Акысыз версиядагы сиздин кызыкчылыктарыңызга негизделген жарнамалар (Google AdMob). Эгер өчүрүлсө, жалпы жарнамаларды көрөсүз.", "attribution_title": "Жарнаманы өлчөө", "attribution_desc": "Anacan колдонмосуна кайсы жарнама аркылуу келгениңизди аныктайт (Meta). iPhone'до Apple'дин уруксат сураган терезеси да чыгат.", "essential_title": "Маанилүү", "essential_desc": "Аккаунт, синхрондоштуруу, эскертүүлөр жана коопсуздук. Ар дайым күйүк болот.", "accept_all": "Баарын кабыл алуу", "reject_all": "Болгону маанилүүлөрү", "customize": "Тандоолорду ыңгайлаштыруу", "save": "Тандоолорду сактоо", "section_title": "Макулдук тандоолору", "section_desc": "Бул түзмөккө тиешелүү. Которгучту өчүргөндө маалымат жөнөтүү дароо токтотулат.", "ump_link": "Google жарнама макулдугунун жөндөөлөрү", "policy_link": "Купуялуулук саясаты", "settings_row": "Макулдук тандоолору", "settings_row_desc": "Аналитика, жарнамалар жана өлчөө", "saved": "Тандоолоруңуз сакталды", "always_on": "Ар дайым күйүк"},
  "et": {"sheet_title": "Sinu privaatsus on esikohal", "sheet_body": "Sinu terviseandmeid ei jagata kunagi reklaamide ega analüütika jaoks. Need valikud puudutavad ainult rakenduse kasutusstatistikat ja reklaame. Saad neid igal ajal Privaatsuse all muuta.", "analytics_title": "Analüütika", "analytics_desc": "Anonüümne kasutusstatistika, mis aitab meil rakendust täiustada (Google Firebase). Tsükli kuupäevad, sümptomid ja muud terviseandmed ei ole kaasatud.", "ads_title": "Isikupärastatud reklaamid", "ads_desc": "Sinu huvidel põhinevad reklaamid tasuta versioonis (Google AdMob). Kui see on välja lülitatud, näed üldiseid reklaame.", "attribution_title": "Reklaamide mõõtmine", "attribution_desc": "Mõõdab, milline reklaam sind Anacani tõi (Meta). iPhone'is ilmub ka Apple'i loaaken.", "essential_title": "Hädavajalik", "essential_desc": "Konto, sünkroonimine, meeldetuletused ja turvalisus. Alati sees.", "accept_all": "Nõustu kõigiga", "reject_all": "Ainult hädavajalik", "customize": "Kohanda valikuid", "save": "Salvesta minu valikud", "section_title": "Nõusoleku valikud", "section_desc": "Kehtib selles seadmes. Lüliti väljalülitamine peatab andmete saatmise kohe.", "ump_link": "Google'i reklaamide nõusoleku seaded", "policy_link": "Privaatsuspoliitika", "settings_row": "Nõusoleku valikud", "settings_row_desc": "Analüütika, reklaamid ja mõõtmine", "saved": "Sinu valikud on salvestatud", "always_on": "Alati sees"},
  "tk": {"sheet_title": "Siziň gizlinligiňiz birinji orunda", "sheet_body": "Saglyk ýazgylaryňyz mahabat ýa-da analitika üçin hiç haçan paýlaşylmaýar. Bu saýlawlar diňe programmanyň ulanyş statistikasyna we mahabatlara degişli. Olary islän wagtyňyz Gizlinlik bölüminde üýtgedip bilersiňiz.", "analytics_title": "Analitika", "analytics_desc": "Programmany gowulandyrmaga kömek edýän näbelli ulanyş statistikasy (Google Firebase). Sikl seneleri, alamatlar we beýleki saglyk ýazgylary goşulmaýar.", "ads_title": "Şahsylaşdyrylan mahabatlar", "ads_desc": "Mugt wersiýada gyzyklanmalaryňyza esaslanýan mahabatlar (Google AdMob). Öçürilse, umumy mahabatlary görersiňiz.", "attribution_title": "Mahabat ölçegi", "attribution_desc": "Sizi Anacan-a haýsy mahabatyň getirendigini ölçeýär (Meta). iPhone-da Apple-yň rugsat penjiresi hem peýda bolar.", "essential_title": "Möhüm", "essential_desc": "Hasap, sinhronlaşdyrma, ýatlatmalar we howpsuzlyk. Hemişe açyk.", "accept_all": "Hemmesini kabul etmek", "reject_all": "Diňe zerurlary", "customize": "Saýlawlary sazlamak", "save": "Saýlawlarymy saklamak", "section_title": "Razylyk saýlawlary", "section_desc": "Bu enjama degişli. Açary öçürmek ibermegi derrew togtadýar.", "ump_link": "Google mahabat razylyk sazlamalary", "policy_link": "Gizlinlik syýasaty", "settings_row": "Razylyk saýlawlary", "settings_row_desc": "Analitika, mahabatlar we ölçeg", "saved": "Saýlawlaryňyz saklandy", "always_on": "Hemişe açyk"},
  "uk": {"sheet_title": "Ваша конфіденційність — понад усе", "sheet_body": "Ваші медичні записи ніколи не передаються для реклами чи аналітики. Ці налаштування стосуються лише статистики використання застосунку та реклами. Ви можете змінити їх будь-коли в розділі «Конфіденційність».", "analytics_title": "Аналітика", "analytics_desc": "Анонімна статистика використання, яка допомагає нам покращувати застосунок (Google Firebase). Дати циклу, симптоми та інші медичні записи не включаються.", "ads_title": "Персоналізована реклама", "ads_desc": "Реклама в безкоштовній версії на основі ваших інтересів (Google AdMob). Якщо вимкнено, ви бачите загальну рекламу.", "attribution_title": "Вимірювання реклами", "attribution_desc": "Визначає, яка реклама привела вас до Anacan (Meta). На iPhone також з’явиться вікно дозволу Apple.", "essential_title": "Основне", "essential_desc": "Обліковий запис, синхронізація, нагадування та безпека. Завжди ввімкнено.", "accept_all": "Прийняти все", "reject_all": "Лише необхідні", "customize": "Налаштувати вибір", "save": "Зберегти мій вибір", "section_title": "Налаштування згоди", "section_desc": "Застосовується до цього пристрою. Вимкнення перемикача одразу припиняє надсилання.", "ump_link": "Налаштування згоди на рекламу Google", "policy_link": "Політика конфіденційності", "settings_row": "Налаштування згоди", "settings_row_desc": "Аналітика, реклама та вимірювання", "saved": "Ваш вибір збережено", "always_on": "Завжди ввімкнено"},
};

