  "zh": <String, Object>{"pregnancy_week": "{w}周{d}天", "pregnancy_week_only": "{w}周", "baby_size": "宝宝大小：{fruit}", "days_left": "还剩 {n} 天", "trimester": "孕{n}期", "baby_days": "{d}天", "baby_months": "{m}个月{d}天", "baby_years": "{y}岁{m}个月", "last_feed": "上次喂奶", "next_nap": "下次小睡", "bedtime": "夜间睡眠", "sleeping": "正在睡", "awake": "醒着", "today": "今天", "feeds": "喂养", "sleep": "睡眠", "diapers": "尿布", "sides": <String, Object>{"left": "左侧", "right": "右侧", "formula": "配方奶", "solid": "辅食"}, "minutes": "{n}分钟", "hours_minutes": "{h}小时{m}分", "btn_feed": "喂奶", "btn_sleep": "睡眠", "btn_diaper": "尿布", "btn_woke": "醒了", "premium_title": "获取 Anacan Premium", "premium_body": "在小组件中查看喂养、睡眠和下次小睡预测", "no_data": "暂无记录", "open_app": "打开 Anacan", "hidden": "Anacan", "settings_title": "主屏幕小组件", "settings_eyebrow": "设置", "preview": "预览", "sizes": <String, Object>{"small": "小", "medium": "中", "large": "大", "lock": "锁屏"}, "show_title": "在小组件中显示", "show_feed": "上次喂奶和哺乳侧", "show_feed_sub": "来自喂养记录", "show_nap": "下次小睡预测", "show_nap_sub": "根据清醒窗口", "show_actions": "快捷按钮", "show_actions_sub": "喂奶、睡眠、尿布 — 一触即开", "privacy": "隐私模式", "privacy_sub": "在锁屏上隐藏详情", "premium_badge": "Premium", "premium_note": "喂养和睡眠小组件属于 Premium 功能。没有 Premium 时，小组件会显示“获取 Anacan Premium”。", "how_title": "如何添加？", "how_ios": "在主屏幕空白处长按 → 点击顶部的“+”（或“编辑 → 添加小组件”）→ Anacan → 选择尺寸。", "how_android": "在主屏幕空白处长按 →“小部件”→ Anacan → 将小部件拖到主屏幕。", "how_lock": "锁定屏幕（iPhone）：长按锁定屏幕 →“自定”→ 小组件区域 → Anacan。", "show": "显示", "native_only": "小组件可在 iOS 和 Android App 中使用。", "updated": "小组件已更新", "premium_locked_title": "需要 Anacan Premium", "premium_locked_body": "将小组件添加到主屏幕需要 Premium。这是示例预览。", "word_eyebrow": "今日寄语", "words": <String>["今天对自己温柔一点 — 你做得很好。🌸", "深呼吸。这一刻，还有你，都已足够。💛", "每一个小小的脚步，都是大大的爱。", "你的身体正在孕育奇迹 — 请信任它。", "寻求帮助也是坚强的一部分。", "今天停下来，只为感受一个瞬间。", "重要的是陪伴，而不是完美。", "你的爱是宝宝最好的滋养。🤍", "疲惫也是爱的痕迹 — 给自己一点休息。", "你并不孤单；Anacan 在每一步都陪着你。"], "timer_idle": "没有正在运行的计时器"},
  "id": <String, Object>{"pregnancy_week": "{w} mgg {d} hr", "pregnancy_week_only": "{w} minggu", "baby_size": "Bayi sebesar {fruit}", "days_left": "{n} hari lagi", "trimester": "Trimester {n}", "baby_days": "{d} hari", "baby_months": "{m} bln {d} hr", "baby_years": "{y} thn {m} bln", "last_feed": "Menyusu terakhir", "next_nap": "Tidur berikutnya", "bedtime": "Tidur malam", "sleeping": "Sedang tidur", "awake": "Terjaga", "today": "Hari ini", "feeds": "Menyusu", "sleep": "Tidur", "diapers": "Popok", "sides": <String, Object>{"left": "Payudara kiri", "right": "Payudara kanan", "formula": "Susu formula", "solid": "MPASI"}, "minutes": "{n} mnt", "hours_minutes": "{h} j {m} m", "btn_feed": "Menyusu", "btn_sleep": "Tidur", "btn_diaper": "Popok", "btn_woke": "Bangun", "premium_title": "Dapatkan Anacan Premium", "premium_body": "Menyusu, tidur, dan prediksi tidur di widget", "no_data": "Belum ada catatan", "open_app": "Buka Anacan", "hidden": "Anacan", "settings_title": "Widget Layar Utama", "settings_eyebrow": "Pengaturan", "preview": "Pratinjau", "sizes": <String, Object>{"small": "Kecil", "medium": "Sedang", "large": "Besar", "lock": "Kunci"}, "show_title": "Tampilkan di widget", "show_feed": "Menyusu terakhir dan sisi payudara", "show_feed_sub": "Dari pelacak menyusui", "show_nap": "Prediksi tidur berikutnya", "show_nap_sub": "Berdasarkan jendela terjaga", "show_actions": "Tombol cepat", "show_actions_sub": "Menyusu, tidur, popok — sekali ketuk", "privacy": "Mode privat", "privacy_sub": "Sembunyikan detail di Layar Terkunci", "premium_badge": "Premium", "premium_note": "Widget menyusu dan tidur termasuk Premium. Tanpa Premium, widget akan menampilkan “Dapatkan Anacan Premium”.", "how_title": "Bagaimana cara menambahkannya?", "how_ios": "Sentuh dan tahan area kosong di Layar Utama → “+” di atas (atau “Edit → Tambah Widget”) → Anacan → pilih ukuran.", "how_android": "Sentuh dan tahan area kosong di layar utama → “Widget” → Anacan → seret widget ke layar.", "how_lock": "Layar Terkunci (iPhone): sentuh dan tahan Layar Terkunci → “Sesuaikan” → area widget → Anacan.", "show": "Tampilkan", "native_only": "Widget berfungsi di aplikasi iOS dan Android.", "updated": "Widget diperbarui", "premium_locked_title": "Perlu Anacan Premium", "premium_locked_body": "Premium diperlukan untuk menambahkan widget ke layar utamamu. Ini hanya pratinjau contoh.", "word_eyebrow": "Kata hari ini", "words": <String>["Hari ini bersikaplah sedikit lebih lembut pada dirimu — kamu hebat. 🌸", "Tarik napas. Momen ini, dan kamu, sudah cukup. 💛", "Setiap langkah kecil adalah cinta yang besar.", "Tubuhmu sedang menciptakan keajaiban — percayalah padanya.", "Meminta bantuan adalah bagian dari menjadi kuat.", "Berhentilah sejenak hari ini untuk merasakan satu momen.", "Yang penting hadir, bukan menjadi sempurna.", "Cintamu adalah makanan terbesar bagi bayimu. 🤍", "Lelah pun adalah jejak cinta — berilah dirimu istirahat.", "Kamu tidak sendiri; Anacan menemanimu di setiap langkah."], "timer_idle": "Tidak ada timer berjalan"},
  "fr": <String, Object>{"pregnancy_week": "{w} sem. {d} j", "pregnancy_week_only": "{w} semaines", "baby_size": "Taille de bébé : {fruit}", "days_left": "Encore {n} jours", "trimester": "{n}e trimestre", "baby_days": "{d} jours", "baby_months": "{m} mois {d} j", "baby_years": "{y} an(s) {m} mois", "last_feed": "Dernier repas", "next_nap": "Prochaine sieste", "bedtime": "Coucher", "sleeping": "Dort", "awake": "Éveillé", "today": "Aujourd'hui", "feeds": "Repas", "sleep": "Sommeil", "diapers": "Couches", "sides": <String, Object>{"left": "Sein gauche", "right": "Sein droit", "formula": "Biberon", "solid": "Diversification"}, "minutes": "{n} min", "hours_minutes": "{h} h {m} min", "btn_feed": "Repas", "btn_sleep": "Sommeil", "btn_diaper": "Couche", "btn_woke": "Réveillé", "premium_title": "Passez à Anacan Premium", "premium_body": "Repas, sommeil et prochaine sieste dans le widget", "no_data": "Aucune entrée pour l'instant", "open_app": "Ouvrir Anacan", "hidden": "Anacan", "settings_title": "Widgets de l'écran d'accueil", "settings_eyebrow": "Réglages", "preview": "Aperçu", "sizes": <String, Object>{"small": "Petit", "medium": "Moyen", "large": "Grand", "lock": "Verrouillage"}, "show_title": "Afficher dans le widget", "show_feed": "Dernier repas et côté du sein", "show_feed_sub": "Depuis le suivi des repas", "show_nap": "Prévision de la prochaine sieste", "show_nap_sub": "Selon la fenêtre d'éveil", "show_actions": "Boutons rapides", "show_actions_sub": "Repas, sommeil, couche — en un toucher", "privacy": "Mode privé", "privacy_sub": "Masquer les détails sur l'écran verrouillé", "premium_badge": "Premium", "premium_note": "Les widgets repas et sommeil font partie de Premium. Sans Premium, le widget affiche « Passez à Anacan Premium ».", "how_title": "Comment l'ajouter ?", "how_ios": "Maintenez le doigt sur un espace vide de l'écran d'accueil → « + » en haut (ou « Modifier → Ajouter un widget ») → Anacan → choisissez la taille.", "how_android": "Maintenez le doigt sur un espace vide de l'écran d'accueil → « Widgets » → Anacan → faites glisser le widget sur l'écran.", "how_lock": "Écran verrouillé (iPhone) : maintenez le doigt sur l'écran verrouillé → « Personnaliser » → zone des widgets → Anacan.", "show": "Afficher", "native_only": "Les widgets fonctionnent dans l'app iOS et Android.", "updated": "Widget mis à jour", "premium_locked_title": "Anacan Premium requis", "premium_locked_body": "Premium est nécessaire pour ajouter le widget à ton écran d'accueil. Ceci est un aperçu d'exemple.", "word_eyebrow": "Mot du jour", "words": <String>["Sois un peu plus douce avec toi aujourd'hui — tu fais un travail formidable. 🌸", "Respire. Cet instant, et toi aussi, vous suffisez. 💛", "Chaque petit pas est un grand geste d'amour.", "Ton corps accomplit un miracle — fais-lui confiance.", "Demander de l'aide fait partie de la force.", "Fais une pause aujourd'hui, juste pour ressentir un instant.", "L'important, c'est d'être là, pas d'être parfaite.", "Ton amour est la plus grande nourriture pour ton bébé. 🤍", "La fatigue aussi est une trace d'amour — accorde-toi du repos.", "Tu n'es pas seule ; Anacan est à tes côtés à chaque pas."], "timer_idle": "Aucun minuteur en cours"},
  "es": <String, Object>{"pregnancy_week": "{w} sem. {d} días", "pregnancy_week_only": "{w} semanas", "baby_size": "Tamaño del bebé: {fruit}", "days_left": "Faltan {n} días", "trimester": "Trimestre {n}", "baby_days": "{d} días", "baby_months": "{m} m {d} d", "baby_years": "{y} a {m} m", "last_feed": "Última toma", "next_nap": "Próxima siesta", "bedtime": "Sueño nocturno", "sleeping": "Durmiendo", "awake": "Despierto", "today": "Hoy", "feeds": "Tomas", "sleep": "Sueño", "diapers": "Pañales", "sides": <String, Object>{"left": "Pecho izq.", "right": "Pecho der.", "formula": "Fórmula", "solid": "Sólidos"}, "minutes": "{n} min", "hours_minutes": "{h} h {m} min", "btn_feed": "Toma", "btn_sleep": "Sueño", "btn_diaper": "Pañal", "btn_woke": "Despertó", "premium_title": "Hazte Anacan Premium", "premium_body": "Tomas, sueño y próxima siesta en el widget", "no_data": "Aún no hay registros", "open_app": "Abrir Anacan", "hidden": "Anacan", "settings_title": "Widgets de la pantalla de inicio", "settings_eyebrow": "Ajustes", "preview": "Vista previa", "sizes": <String, Object>{"small": "Pequeño", "medium": "Mediano", "large": "Grande", "lock": "Bloqueo"}, "show_title": "Mostrar en el widget", "show_feed": "Última toma y lado del pecho", "show_feed_sub": "Del registro de tomas", "show_nap": "Previsión de la próxima siesta", "show_nap_sub": "Según la ventana de vigilia", "show_actions": "Botones rápidos", "show_actions_sub": "Toma, sueño, pañal — con un toque", "privacy": "Modo privado", "privacy_sub": "Ocultar detalles en la pantalla bloqueada", "premium_badge": "Premium", "premium_note": "Los widgets de tomas y sueño son parte de Premium. Sin Premium, el widget mostrará «Hazte Anacan Premium».", "how_title": "¿Cómo lo añado?", "how_ios": "Mantén pulsado un espacio vacío de la pantalla de inicio → «+» arriba (o «Editar → Añadir widget») → Anacan → elige el tamaño.", "how_android": "Mantén pulsado un espacio vacío de la pantalla de inicio → «Widgets» → Anacan → arrastra el widget a la pantalla.", "how_lock": "Pantalla bloqueada (iPhone): mantén pulsada la pantalla bloqueada → «Personalizar» → zona de widgets → Anacan.", "show": "Mostrar", "native_only": "Los widgets funcionan en la app de iOS y Android.", "updated": "Widget actualizado", "premium_locked_title": "Se requiere Anacan Premium", "premium_locked_body": "Necesitas Premium para añadir el widget a tu pantalla de inicio. Esta es una vista previa de ejemplo.", "word_eyebrow": "Palabra del día", "words": <String>["Hoy sé un poquito más amable contigo — lo estás haciendo genial. 🌸", "Respira. Este momento, y tú, sois suficiente. 💛", "Cada pequeño paso es un gran gesto de amor.", "Tu cuerpo está haciendo un milagro — confía en él.", "Pedir ayuda también es ser fuerte.", "Haz una pausa hoy solo para sentir un momento.", "Lo importante es estar ahí, no ser perfecta.", "Tu amor es el mayor alimento para tu bebé. 🤍", "El cansancio también es una huella de amor — date un descanso.", "No estás sola; Anacan te acompaña en cada paso."], "timer_idle": "Ningún temporizador activo"},
  "pt": <String, Object>{"pregnancy_week": "{w} sem. {d} dias", "pregnancy_week_only": "{w} semanas", "baby_size": "Tamanho do bebê: {fruit}", "days_left": "Faltam {n} dias", "trimester": "{n}º trimestre", "baby_days": "{d} dias", "baby_months": "{m} m {d} d", "baby_years": "{y} a {m} m", "last_feed": "Última mamada", "next_nap": "Próxima soneca", "bedtime": "Sono noturno", "sleeping": "Dormindo", "awake": "Acordado", "today": "Hoje", "feeds": "Mamadas", "sleep": "Sono", "diapers": "Fraldas", "sides": <String, Object>{"left": "Peito esq.", "right": "Peito dir.", "formula": "Fórmula", "solid": "Papinha"}, "minutes": "{n} min", "hours_minutes": "{h} h {m} min", "btn_feed": "Mamada", "btn_sleep": "Sono", "btn_diaper": "Fralda", "btn_woke": "Acordou", "premium_title": "Assine o Anacan Premium", "premium_body": "Mamadas, sono e próxima soneca no widget", "no_data": "Ainda sem registros", "open_app": "Abrir o Anacan", "hidden": "Anacan", "settings_title": "Widgets da Tela de Início", "settings_eyebrow": "Ajustes", "preview": "Pré-visualização", "sizes": <String, Object>{"small": "Pequeno", "medium": "Médio", "large": "Grande", "lock": "Bloqueio"}, "show_title": "Mostrar no widget", "show_feed": "Última mamada e lado do peito", "show_feed_sub": "Do registro de mamadas", "show_nap": "Previsão da próxima soneca", "show_nap_sub": "Pela janela de vigília", "show_actions": "Botões rápidos", "show_actions_sub": "Mamada, sono, fralda — com um toque", "privacy": "Modo privado", "privacy_sub": "Ocultar detalhes na Tela Bloqueada", "premium_badge": "Premium", "premium_note": "Os widgets de mamada e sono fazem parte do Premium. Sem Premium, o widget mostra “Assine o Anacan Premium”.", "how_title": "Como adicionar?", "how_ios": "Toque e mantenha pressionado um espaço vazio da Tela de Início → “+” no topo (ou “Editar → Adicionar Widget”) → Anacan → escolha o tamanho.", "how_android": "Toque e mantenha pressionado um espaço vazio da tela inicial → “Widgets” → Anacan → arraste o widget p